state.adapter_ts:
/**
 * Provider adapter: validates raw System One answers and turns them into
 * contract Measurements.
 *
 * The rules are deliberately strict. A malformed answer is reported with every
 * violated expectation and is never silently repaired: no renormalization, no
 * filling missing candidates, no reading probabilities out of free text. The
 * accepted shapes follow the TypeSafe HTTP API reference for `POST
 * /v1/systemone` (Noul, Choice, Score) as of 2026-09-18.
 */
import type { Measurement } from "./contracts.js";

export interface AdapterIssue {
  path: string;
  message: string;
}

export type AdapterResult<T> = { ok: true; value: T } | { ok: false; issues: AdapterIssue[] };

/** Distributions must sum to 1 within this tolerance; outside it, the answer is malformed. */
export const DISTRIBUTION_SUM_TOLERANCE = 1e-6;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function finiteNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

function probability(value: unknown): value is number {
  return finiteNumber(value) && value >= 0 && value <= 1;
}

function unexpectedFields(record: Record<string, unknown>, allowed: string[], path: string): AdapterIssue[] {
  const issues: AdapterIssue[] = [];
  for (const key of Object.keys(record)) {
    if (!allowed.includes(key)) {
      issues.push({ path: `${path}/${key}`, message: "unexpected field in a model answer" });
    }
  }
  return issues;
}

function checkDistribution(
  raw: unknown,
  expectedKeys: string[],
  path: string,
): { issues: AdapterIssue[]; distribution: Record<string, number> } {
  const issues: AdapterIssue[] = [];
  if (!isRecord(raw)) {
    return { issues: [{ path, message: "probabilities must be an object" }], distribution: {} };
  }
  const distribution: Record<string, number> = {};
  for (const key of expectedKeys) {
    if (!(key in raw)) issues.push({ path: `${path}/${key}`, message: "missing candidate in the returned distribution" });
  }
  for (const [key, value] of Object.entries(raw)) {
    if (!expectedKeys.includes(key)) {
      issues.push({ path: `${path}/${key}`, message: "candidate was not offered in the request" });
      continue;
    }
    if (!probability(value)) {
      issues.push({ path: `${path}/${key}`, message: "probability must be finite and between 0 and 1" });
      continue;
    }
    distribution[key] = value;
  }
  const sum = Object.values(distribution).reduce((total, value) => total + value, 0);
  if (Object.keys(distribution).length === expectedKeys.length && Math.abs(sum - 1) > DISTRIBUTION_SUM_TOLERANCE) {
    issues.push({
      path,
      message: `probabilities must sum to 1 within ${DISTRIBUTION_SUM_TOLERANCE}; got ${sum}`,
    });
  }
  return { issues, distribution };
}

export interface NoulAnswerValue {
  type: "noul";
  noul: number;
}

export function parseNoulAnswer(answer: unknown): AdapterResult<NoulAnswerValue> {
  if (!isRecord(answer)) return { ok: false, issues: [{ path: "/", message: "answer must be an object" }] };
  const issues = unexpectedFields(answer, ["type", "noul"], "");
  if (answer.type !== "noul") issues.push({ path: "/type", message: 'answer type must be "noul"' });
  if (!probability(answer.noul)) issues.push({ path: "/noul", message: "noul must be a finite probability between 0 and 1" });
  if (issues.length > 0) return { ok: false, issues };
  return { ok: true, value: { type: "noul", noul: answer.noul as number } };
}

export interface ChoiceAnswerValue {
  type: "choice";
  choice: string;
  probabilities: Record<string, number>;
  confidence: number;
}

export function parseChoiceAnswer(answer: unknown, optionIds: string[]): AdapterResult<ChoiceAnswerValue> {
  if (!isRecord(answer)) return { ok: false, issues: [{ path: "/", message: "answer must be an object" }] };
  const issues = unexpectedFields(answer, ["type", "choice", "probabilities", "confidence"], "");
  if (answer.type !== "choice") issues.push({ path: "/type", message: 'answer type must be "choice"' });
  const { issues: distributionIssues, distribution } = checkDistribution(answer.probabilities, optionIds, "/probabilities");
  issues.push(...distributionIssues);
  if (typeof answer.choice !== "string" || !optionIds.includes(answer.choice)) {
    issues.push({ path: "/choice", message: "choice must name one of the offered options" });
  } else {
    const top = Math.max(...Object.values(distribution));
    if ((distribution[answer.choice] ?? 0) + 1e-9 < top) {
      issues.push({ path: "/choice", message: "choice is not the highest-probability option" });
    }
  }
  if (!probability(answer.confidence)) issues.push({ path: "/confidence", message: "confidence must be a finite probability between 0 and 1" });
  if (issues.length > 0) return { ok: false, issues };
  return {
    ok: true,
    value: {
      type: "choice",
      choice: answer.choice as string,
      probabilities: distribution,
      confidence: answer.confidence as number,
    },
  };
}

export interface ScoreAnswerValue {
  type: "score";
  score: number;
  probabilities: Record<string, number>;
  confidence: number;
}

export function parseScoreAnswer(answer: unknown, levelCount: number): AdapterResult<ScoreAnswerValue> {
  if (!isRecord(answer)) return { ok: false, issues: [{ path: "/", message: "answer must be an object" }] };
  const levelKeys = Array.from({ length: levelCount }, (_unused, index) => String(index));
  const issues = unexpectedFields(answer, ["type", "score", "legend", "probabilities", "confidence"], "");
  if (answer.type !== "score") issues.push({ path: "/type", message: 'answer type must be "score"' });
  const { issues: distributionIssues, distribution } = checkDistribution(answer.probabilities, levelKeys, "/probabilities");
  issues.push(...distributionIssues);
  const legend = answer.legend;
  if (!isRecord(legend) || levelKeys.some(key => !(key in legend))) {
    issues.push({ path: "/legend", message: "legend must map every level number to its description" });
  }
  if (!finiteNumber(answer.score)) {
    issues.push({ path: "/score", message: "score must be a finite number" });
  } else if (Object.keys(distribution).length === levelCount) {
    const weighted = levelKeys.reduce((total, key) => total + Number(key) * (distribution[key] ?? 0), 0);
    if (Math.abs(answer.score - weighted) > DISTRIBUTION_SUM_TOLERANCE) {
      issues.push({ path: "/score", message: `score ${answer.score} does not match its own probability-weighted mean ${weighted}` });
    }
  }
  if (!probability(answer.confidence)) issues.push({ path: "/confidence", message: "confidence must be a finite probability between 0 and 1" });
  if (issues.length > 0) return { ok: false, issues };
  return {
    ok: true,
    value: {
      type: "score",
      score: answer.score as number,
      probabilities: distribution,
      confidence: answer.confidence as number,
    },
  };
}

export interface ParsedSystemOneResponse {
  model: string;
  answers: Record<string, unknown>;
  usage?: { inputTokens?: number; outputTokens?: number };
}

/** Validates the response envelope and that answers cover exactly the asked question ids. */
export function parseSystemOneResponse(payload: unknown, expectedQuestionIds: string[]): AdapterResult<ParsedSystemOneResponse> {
  if (!isRecord(payload)) return { ok: false, issues: [{ path: "/", message: "response must be an object" }] };
  const issues = unexpectedFields(payload, ["model", "answers", "usage"], "");
  if (typeof payload.model !== "string" || payload.model === "") {
    issues.push({ path: "/model", message: "response must name the model" });
  }
  if (!isRecord(payload.answers)) {
    issues.push({ path: "/answers", message: "answers must be an object" });
    return { ok: false, issues };
  }
  for (const id of expectedQuestionIds) {
    if (!(id in payload.answers)) issues.push({ path: `/answers/${id}`, message: "answer is missing for an asked question" });
  }
  for (const key of Object.keys(payload.answers)) {
    if (!expectedQuestionIds.includes(key)) {
      issues.push({ path: `/answers/${key}`, message: "answer was returned for a question that was not asked" });
    }
  }
  if (issues.length > 0) return { ok: false, issues };
  const usage: ParsedSystemOneResponse["usage"] = {};
  if (isRecord(payload.usage)) {
    if (finiteNumber(payload.usage.input_tokens)) usage.inputTokens = payload.usage.input_tokens;
    if (finiteNumber(payload.usage.output_tokens)) usage.outputTokens = payload.usage.output_tokens;
  }
  return {
    ok: true,
    value: { model: payload.model as string, answers: payload.answers as Record<string, unknown>, usage },
  };
}

export function noulMeasurement(pTrue: number): Measurement {
  return { kind: "boolean", representation: "distribution", pTrue, probabilitySource: "model_distribution" };
}

export function choiceMeasurement(distribution: Record<string, number>): Measurement {
  return { kind: "categorical", representation: "distribution", distribution, probabilitySource: "model_distribution" };
}

export function scoreMeasurement(distribution: Record<string, number>): Measurement {
  return { kind: "ordinal", representation: "distribution", distribution, probabilitySource: "model_distribution" };
}

state.screening_ts:
/**
 * Semantic screening: builds small meta-questions about each QuestionSpec and
 * turns validated Noul answers into model_signal diagnostics.
 *
 * The model never sees state values, expected diagnostics, or rule
 * thresholds: the sent state contains the question text and field descriptors
 * only. Diagnostics are assembled here from the rule pack, so a candidate
 * answer cannot change severity, rule identity, or output shape.
 */
import { parseNoulAnswer, parseSystemOneResponse } from "./adapter.js";
import type {
  Diagnostic,
  Json,
  QuestionSpec,
  QuestionSuite,
  RecordedResponse,
  ScreeningObservation,
  ScreeningPack,
  ScreeningPolicy,
  ScreeningReport,
  ScreeningRequest,
  ScreeningRuleDefinition,
  ScreeningRuleView,
  ScreeningSubQuestion,
} from "./contracts.js";
import { digestOf } from "./digest.js";

export class ScreeningError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "ScreeningError";
  }
}

export const SCREENING_POLICY: ScreeningPolicy = {
  policyId: "screening-reference-v0.1",
  applicabilityAtLeast: 0.8,
  sufficiencyAtLeast: 0.8,
  signalAtLeast: 0.5,
  note: "Uncalibrated defaults for the reference implementation. Choose thresholds on validation data before relying on them; a signal is a model_signal, not a verdict.",
};

export function ruleApplies(rule: ScreeningRuleDefinition, question: QuestionSpec): boolean {
  const { modes, outputKinds } = rule.appliesTo;
  if (modes !== undefined && !modes.includes(question.mode)) return false;
  if (outputKinds !== undefined && !outputKinds.includes(question.output.kind)) return false;
  return true;
}

function describeOutput(output: QuestionSpec["output"]): Json {
  if (output.kind === "boolean") {
    return { kind: "boolean", criteria: { true: output.criteria.true, false: output.criteria.false } };
  }
  if (output.kind === "categorical") {
    return {
      kind: "categorical",
      selection: output.selection,
      options: output.options.map(option => ({ id: option.id, description: option.description })),
      ...(output.fallbackOptionId === undefined ? {} : { fallbackOptionId: output.fallbackOptionId }),
      ...(output.tieBreak === undefined ? {} : { tieBreak: output.tieBreak }),
    };
  }
  return {
    kind: "ordinal",
    axis: output.axis,
    levels: output.levels.map(level => ({ id: level.id, description: level.description })),
  };
}

function describeField(suite: QuestionSuite, fieldId: string): Json {
  const field = suite.state.fields.find(candidate => candidate.id === fieldId);
  if (!field) throw new ScreeningError(`question references unknown field ${fieldId}`);
  return {
    fieldId: field.id,
    pointer: field.pointer,
    valueType: field.valueType,
    nullable: field.nullable,
    role: field.role,
  };
}

function subQuestion(id: string, definition: { instructions: string; criteria: { true: string; false: string } }): ScreeningSubQuestion {
  return { type: "noul", instructions: definition.instructions, criteria: definition.criteria };
}

export function buildScreeningRequests(suite: QuestionSuite, pack: ScreeningPack): ScreeningRequest[] {
  const model = pack.model ?? "jev-latest";
  const requests: ScreeningRequest[] = [];
  suite.questions.forEach((question, questionIndex) => {
    const rules = pack.rules.filter(rule => ruleApplies(rule, question));
    if (rules.length === 0) return;
    const state: Json = {
      question: {
        instructions: question.instructions,
        mode: question.mode,
        applicability: question.applicability,
        evidenceBoundary: question.evidenceBoundary,
        output: describeOutput(question.output),
        inputs: question.inputs.map(fieldId => describeField(suite, fieldId)),
        policyRefs: question.policyRefs.map(fieldId => describeField(suite, fieldId)),
      },
    };
    const questions: Record<string, ScreeningSubQuestion> = {};
    const ruleViews: ScreeningRuleView[] = [];
    for (const rule of rules) {
      const subQuestionIds = {
        applicability: `${rule.id}__applicability`,
        sufficiency: `${rule.id}__sufficiency`,
        violation: `${rule.id}__violation`,
      };
      questions[subQuestionIds.applicability] = subQuestion(subQuestionIds.applicability, rule.applicability);
      questions[subQuestionIds.sufficiency] = subQuestion(subQuestionIds.sufficiency, rule.sufficiency);
      questions[subQuestionIds.violation] = subQuestion(subQuestionIds.violation, rule.violation);
      ruleViews.push({ ruleId: rule.id, summary: rule.summary, subQuestionIds });
    }
    requests.push({
      questionId: question.id,
      questionIndex,
      state,
      questions,
      rules: ruleViews,
      requestDigest: digestOf({ model, state, questions }),
    });
  });
  return requests;
}

export function screeningReportDigest(report: ScreeningReport): string {
  const { digest: _digest, ...rest } = report;
  return digestOf(rest);
}

export function screenFromRecordings(
  suite: QuestionSuite,
  pack: ScreeningPack,
  recordings: RecordedResponse[],
  version: string,
  policy: ScreeningPolicy = SCREENING_POLICY,
): ScreeningReport {
  const requests = buildScreeningRequests(suite, pack);
  const byDigest = new Map<string, Json>();
  for (const recording of recordings) {
    if (byDigest.has(recording.requestDigest)) {
      throw new ScreeningError(`duplicate recorded response for ${recording.requestDigest}`);
    }
    byDigest.set(recording.requestDigest, recording.response);
  }

  const observations: ScreeningObservation[] = [];
  const diagnostics: Diagnostic[] = [];

  for (const request of requests) {
    const response = byDigest.get(request.requestDigest);
    if (response === undefined) {
      for (const rule of request.rules) {
        observations.push({ questionId: request.questionId, ruleId: rule.ruleId, status: "not_run" });
      }
      continue;
    }
    const expectedIds = request.rules.flatMap(rule => [
      rule.subQuestionIds.applicability,
      rule.subQuestionIds.sufficiency,
      rule.subQuestionIds.violation,
    ]);
    const envelope = parseSystemOneResponse(response, expectedIds);
    if (!envelope.ok) {
      const problems = envelope.issues.map(issue => `${issue.path} ${issue.message}`);
      for (const rule of request.rules) {
        observations.push({ questionId: request.questionId, ruleId: rule.ruleId, status: "malformed", problems });
      }
      continue;
    }
    for (const rule of request.rules) {
      const parsed = {
        applicability: parseNoulAnswer(envelope.value.answers[rule.subQuestionIds.applicability]),
        sufficiency: parseNoulAnswer(envelope.value.answers[rule.subQuestionIds.sufficiency]),
        violation: parseNoulAnswer(envelope.value.answers[rule.subQuestionIds.violation]),
      };
      const failed = Object.entries(parsed).filter(entry => !entry[1].ok);
      if (failed.length > 0) {
        const problems = failed.flatMap(([dimension, result]) => result.ok
          ? []
          : result.issues.map(issue => `${dimension}${issue.path} ${issue.message}`));
        observations.push({ questionId: request.questionId, ruleId: rule.ruleId, status: "malformed", problems });
        continue;
      }
      const applicability = parsed.applicability.ok ? parsed.applicability.value.noul : 0;
      const sufficiency = parsed.sufficiency.ok ? parsed.sufficiency.value.noul : 0;
      const violation = parsed.violation.ok ? parsed.violation.value.noul : 0;
      const probabilities = { applicability, sufficiency, violation };
      if (applicability < policy.applicabilityAtLeast) {
        observations.push({ questionId: request.questionId, ruleId: rule.ruleId, status: "not_applicable", ...probabilities });
        continue;
      }
      if (sufficiency < policy.sufficiencyAtLeast) {
        observations.push({ questionId: request.questionId, ruleId: rule.ruleId, status: "inconclusive", ...probabilities });
        continue;
      }
      if (violation >= policy.signalAtLeast) {
        observations.push({ questionId: request.questionId, ruleId: rule.ruleId, status: "signal", ...probabilities });
        const definition = pack.rules.find(candidate => candidate.id === rule.ruleId);
        diagnostics.push({
          ruleId: rule.ruleId,
          questionId: request.questionId,
          severity: "warning",
          basis: "model_signal",
          message: definition?.message ?? rule.summary,
          locations: [{ pointer: `/questions/${request.questionIndex}/instructions` }],
          evidence: [
            { kind: "model_response", runId: request.requestDigest, answerId: rule.subQuestionIds.applicability, modelProbability: applicability },
            { kind: "model_response", runId: request.requestDigest, answerId: rule.subQuestionIds.sufficiency, modelProbability: sufficiency },
            { kind: "model_response", runId: request.requestDigest, answerId: rule.subQuestionIds.violation, modelProbability: violation },
          ],
        });
        continue;
      }
      observations.push({ questionId: request.questionId, ruleId: rule.ruleId, status: "no_signal", ...probabilities });
    }
  }

  const count = (status: ScreeningObservation["status"]): number => observations.filter(observation => observation.status === status).length;
  const withoutDigest = {
    schemaVersion: "0.1" as const,
    kind: "qlint.screening-report" as const,
    tool: { name: "qlint" as const, version },
    provider: "replay" as const,
    suite: { id: suite.id, digest: digestOf(suite) },
    policy,
    observations,
    diagnostics,
    summary: {
      questions: suite.questions.length,
      requests: requests.length,
      signals: count("signal"),
      inconclusive: count("inconclusive"),
      notRun: count("not_run"),
      malformed: count("malformed"),
    },
    notExecuted: [
      "provider execution (replay only; no network)",
      "threshold calibration",
      "policy excerpts (policyRefs values are not sent, only their descriptors)",
      "suite statistics",
    ],
  };
  return { ...withoutDigest, digest: digestOf(withoutDigest) };
}

